import * as relationMotion from '../src/local-relations-motion';
import {clone,emptyBoard,type Board,type Card} from '../src/model';
class Doc {body?:El;activeElement:El|null=null;frames=new Map<number,()=>void>();counter=0;defaultView={closed:false,getComputedStyle:()=>({getPropertyValue:()=> '0'}),requestAnimationFrame:(fn:()=>void)=>{const id=++this.counter;this.frames.set(id,fn);return id;},cancelAnimationFrame:(id:number)=>{this.frames.delete(id);}};tick(){const frames=[...this.frames.values()];this.frames.clear();frames.forEach(fn=>fn());}}
class El {
 style:Record<string,string>={};clientWidth=320;clientHeight=600;scrollWidth=320;scrollHeight=600;scrollLeft=0;checked=false;hidden=false;children:El[]=[];parentElement?:El;attrs:Record<string,string>={};dataset:Record<string,string>={};classes=new Set<string>();disabled=false;open=false;value='';scrollTop=0;title='';visible=true;selectionStart=0;selectionEnd=0;text='';onclick?:()=>void;oninput?:()=>void;ontoggle?:()=>void;onscroll?:()=>void;
 constructor(readonly tagName:string,readonly ownerDocument:Doc,options:any={}){if(typeof options==='string')options={cls:options};this.text=options.text||'';for(const c of (options.cls||'').split(' ').filter(Boolean))this.classes.add(c);for(const [k,v]of Object.entries(options.attr||{}))this.setAttribute(k,String(v));}
 get childElementCount(){return this.children.length;}get isConnected():boolean{return this.tagName==='ROOT'||!!this.parentElement?.isConnected;}get textContent():string{return this.text+this.children.map(e=>e.textContent).join('');}
 createEl(tag:string,o:any={}){const el=new El(tag.toUpperCase(),this.ownerDocument,o);el.parentElement=this;this.children.push(el);return el;}createSvg(tag:string,o:any={}){return this.createEl(tag,o);}appendChild(el:El){if(el.parentElement)el.parentElement.children=el.parentElement.children.filter(child=>child!==el);el.parentElement=this;this.children.push(el);return el;}remove(){if(this.parentElement)this.parentElement.children=this.parentElement.children.filter(el=>el!==this);this.parentElement=undefined;}getBoundingClientRect(){return{left:0,top:0,width:100,height:50,right:100,bottom:50};}createDiv(o:any={}){return this.createEl('div',o);}createSpan(o:any={}){return this.createEl('span',o);}
 setAttribute(k:string,v:string){this.attrs[k]=v;if(k.startsWith('data-'))this.dataset[k.slice(5).replace(/-([a-z])/g,(_m,c)=>c.toUpperCase())]=v;}getAttribute(k:string){return this.attrs[k]??null;}addClass(...names:string[]){names.forEach(c=>this.classes.add(c));}setText(t:string){this.text=t;}
 contains(el:El|null):boolean{return !!el&&(el===this||this.children.some(e=>e.contains(el)));}empty(){if(this.contains(this.ownerDocument.activeElement))this.ownerDocument.activeElement=null;this.children.forEach(e=>e.parentElement=undefined);this.children=[];this.text='';}
 getClientRects(){return this.visible?[{}]:[];}matches(s:string){if(s.startsWith('.'))return this.classes.has(s.slice(1));if(s.startsWith('[')){const match=s.match(/^\[([^=\]]+)(?:="([^"]*)")?\]$/)!;return this.getAttribute(match[1])!==null&&(match[2]===undefined||this.getAttribute(match[1])===match[2]);}return this.tagName===s.toUpperCase();}
 closest(s:string):El|undefined{return this.matches(s)?this:this.parentElement?.closest(s);}
 querySelectorAll(s:string):El[]{return this.children.flatMap(e=>[...(e.matches(s)?[e]:[]),...e.querySelectorAll(s)]);}querySelector(s:string){return this.querySelectorAll(s)[0];}focus(){if(!this.disabled&&this.isConnected)this.ownerDocument.activeElement=this;}scrollIntoView(){}click(){if(!this.disabled)this.onclick?.();}
}
class Scope {handlers:{modifiers:string[];key:string;func:(event:any)=>unknown}[]=[];constructor(readonly parent?:Scope){}register(modifiers:string[],key:string,func:(event:any)=>unknown){const handler={modifiers,key,func};this.handlers.push(handler);return handler;}}
class ItemView {contentEl:El;app={scope:new Scope(),workspace:{savedLayouts:0,requestSaveLayout(){this.savedLayouts++;},activeView:undefined as ItemView|undefined,getActiveViewOfType(){return this.activeView;},handlers:new Map<string,()=>void>(),on(event:string,fn:()=>void){this.handlers.set(event,fn);return{event,fn};}}};constructor(readonly leaf:{contentEl:El}){this.contentEl=leaf.contentEl;this.app.workspace.activeView=this;}registerEvent(){}registerDomEvent(){} }
const source=readFileSync('src/local-relations-view.ts','utf8').replace(/^import[^\n]*\n/gm,'').replace(/\bexport /g,'');let builds=0;
const deps={...relations,...relationState,...headings,...depth,...relationEdit,...relationMotion,clone,localNeighborhood:(...args:Parameters<typeof relations.localNeighborhood>)=>{builds++;return relations.localNeighborhood(...args);},ItemView,View:ItemView,Scope,setIcon(){}};
const View=new Function(...Object.keys(deps),transformSync(source+'\nreturn LocalRelationsView;',{loader:'ts'}).code)(...Object.values(deps));
const node=(id:string):Card=>({id,kind:'card',title:'对象 '+id,x:0,y:0,width:120,height:80,color:'slate'});
async function fixture(visible=true){const doc=new Doc(),root=new El('ROOT',doc),content=root.createDiv();doc.body=root;content.visible=visible;const board:Board={...emptyBoard(),nodes:'abcdefghi'.split('').map(node),edges:[{id:'ab',from:'a',to:'b',label:'父子',kind:'branch'},{id:'ac',from:'a',to:'c',label:'同级',kind:'branch'},{id:'bd',from:'b',to:'d',label:'理由',direction:'forward'}]};let snapshot:any={board,path:'Board.thoughtspace',name:'Board',selectedId:'b',key:{}},notify=()=>{},unsubscribed=0;const actions:{action:string;id:string;current:()=>boolean}[]=[];
 const host:any={snapshot:()=>snapshot,subscribe:(fn:()=>void)=>{notify=fn;return()=>{unsubscribed++;};},source:()=>({label:'来源',path:'Notes/Source.md',available:true,canExplain:true}),...Object.fromEntries(['locate','openSource','explain'].map(action=>[action,(id:string,current:()=>boolean)=>{actions.push({action,id,current});}]))};const view=new View({contentEl:content},host);await view.onOpen();doc.tick();doc.tick();return{view,doc,content,board,host,actions,notify:()=>notify(),setSnapshot:(s:any)=>snapshot=s,get snapshot(){return snapshot;},get unsubscribed(){return unsubscribed;}};
}
const button=(f:{content:El},key:string)=>f.content.querySelectorAll('[data-relation-focus]').find(e=>e.dataset.relationFocus===key)!;

test('neighbor buttons change only panel center and real back/forward preserve board selection',async()=>{const f=await fixture(),before=JSON.stringify(f.board);assert.equal(f.view.history.current,'b');button(f,'neighbor:parents:a').click();f.doc.tick();assert.equal(f.view.history.current,'a');assert.equal(f.snapshot.selectedId,'b');assert.deepEqual(f.actions,[]);button(f,'back').click();f.doc.tick();assert.equal(f.view.history.current,'b');button(f,'forward').click();f.doc.tick();assert.equal(f.view.history.current,'a');assert.equal(JSON.stringify(f.board),before);});
test('selection follow can be locked independently from pins',async()=>{const f=await fixture();button(f,'pin-center').click();f.doc.tick();f.view.setFollowSelection(false);f.snapshot.selectedId='c';f.notify();f.doc.tick();assert.equal(f.view.history.current,'b');assert.deepEqual(f.view.pins.ids,['b']);f.view.setFollowSelection(true);f.doc.tick();assert.equal(f.view.history.current,'c');assert.deepEqual(f.view.pins.ids,['b']);});
test('explicit center is stable while the board selection remains unchanged',async()=>{const f=await fixture();f.view.setContext('d');f.doc.tick();for(let i=0;i<4;i++){f.notify();f.doc.tick();}assert.equal(f.view.history.current,'d');f.snapshot.selectedId='a';f.notify();f.doc.tick();assert.equal(f.view.history.current,'a');});
test('renaming the same file preserves center history and pins',async()=>{const f=await fixture();f.view.togglePin('b');f.view.setContext('d');f.doc.tick();f.snapshot.path='Renamed.thoughtspace';f.snapshot.name='Renamed';f.notify();f.doc.tick();assert.equal(f.view.history.current,'d');assert.equal(f.view.history.canBack,true);assert.deepEqual(f.view.pins.ids,['b']);assert.match(f.content.textContent,/Renamed/);});
test('switching board identity clears history pins and old query',async()=>{const f=await fixture();f.view.togglePin('b');f.view.query='old';f.setSnapshot({...f.snapshot,key:{},selectedId:'a'});f.notify();f.doc.tick();assert.equal(f.view.history.current,'a');assert.equal(f.view.history.canBack,false);assert.deepEqual(f.view.pins.ids,[]);assert.equal(f.view.query,'');});
test('deleted nodes reconcile both pins and navigation history',async()=>{const f=await fixture();f.view.togglePin('b');f.view.setContext('d');f.doc.tick();f.board.nodes=f.board.nodes.filter(n=>n.id!=='d'&&n.id!=='b');f.board.edges=[];f.notify();f.doc.tick();assert.deepEqual(f.view.pins.ids,[]);assert.equal(f.view.history.current,undefined);assert.match(f.content.textContent,/选择一个中心对象/);});
test('pins stop at six with visible feedback and never alter the board',async()=>{const f=await fixture(),before=JSON.stringify(f.board);for(const id of 'abcdefg')f.view.togglePin(id);f.doc.tick();assert.deepEqual(f.view.pins.ids,['a','b','c','d','e','f']);assert.match(f.content.textContent,/最多固定 6/);assert.equal(JSON.stringify(f.board),before);});
test('typing filters only neighbors and retains search input identity focus and range',async()=>{const f=await fixture(),search=f.content.querySelector('.ts-local-relations-search')!;button(f,'filter-toggle').click();search.focus();search.value='理由';search.selectionStart=1;search.selectionEnd=2;search.oninput?.();f.doc.tick();assert.equal(f.content.querySelector('.ts-local-relations-search'),search);assert.equal(f.doc.activeElement,search);assert.equal(search.selectionStart,1);assert.equal(search.selectionEnd,2);assert.equal(f.view.history.current,'b');assert.match(f.content.textContent,/匹配 1/);assert.match(f.view.counts.title,/每组每页 10 项，总计最多 60/);});
test('necessary render preserves relation disclosure and list scroll',async()=>{const f=await fixture(),group=f.content.querySelectorAll('.ts-local-relations-group')[0];group.open=false;f.view.groupsHost.scrollTop=125;f.notify();f.doc.tick();assert.equal(f.content.querySelectorAll('.ts-local-relations-group')[0].open,false);assert.equal(f.view.groupsHost.scrollTop,125);});
test('hidden panels do not build neighborhoods; visibility resumes one batched render',async()=>{const before=builds,f=await fixture(false);for(let i=0;i<20;i++)f.notify();f.doc.tick();assert.equal(builds,before);f.content.visible=true;f.view.onResize();for(let i=0;i<20;i++)f.notify();assert.equal(f.doc.frames.size,1);f.doc.tick();assert.equal(builds,before+1);});
test('closing removes subscriptions cancels queued rendering and clears temporary pins',async()=>{const f=await fixture();f.view.togglePin('b');const before=builds;assert.equal(f.doc.frames.size,1);await f.view.onClose();f.doc.tick();assert.equal(builds,before);assert.equal(f.unsubscribed,1);assert.deepEqual(f.view.pins.ids,[]);assert.equal(f.content.children.length,0);});
for(const change of ['center','board','document','closed-window','closed-view'])test(`async host callbacks become invalid after ${change}`,async()=>{const f=await fixture();button(f,'source').click();assert.equal(f.actions.length,1);assert.equal(f.actions[0].current(),true);if(change==='center')f.view.setContext('c');if(change==='board')f.setSnapshot({...f.snapshot,key:{}});if(change==='document')Object.defineProperty(f.content,'ownerDocument',{value:new Doc()});if(change==='closed-window')f.doc.defaultView.closed=true;if(change==='closed-view')await f.view.onClose();assert.equal(f.actions[0].current(),false);});
test('missing sources disable explicit source actions without blocking board locate',async()=>{const f=await fixture();f.host.source=()=>({label:'来源',path:'Missing.md',available:false,reason:'来源笔记已删除',canExplain:false});f.notify();f.doc.tick();assert.equal(button(f,'source').disabled,true);assert.equal(button(f,'explain').disabled,true);assert.equal(button(f,'locate').disabled,false);assert.match(f.content.textContent,/来源笔记已删除/);button(f,'locate').click();assert.equal(f.actions[0].id,'b');});


test('graph mode draws relation lines for actual visible neighbors and no geometry changes',async()=>{const f=await fixture();assert.equal(f.view.getDisplayText(),'独立关系浏览');assert.equal(f.content.querySelectorAll('[data-relation-kind]').length,3);assert.ok(f.content.querySelector('.ts-local-relations-lines'));const paths=f.content.querySelectorAll('path');assert.equal(paths.filter(p=>p.getAttribute('data-kind')!==null).length,3);assert.equal(paths.find(p=>p.getAttribute('data-kind')==='siblings')?.getAttribute('stroke-dasharray'),'3 4');});
test('layout refresh does not invalidate navigation but hiding cancels a source action',async()=>{const f=await fixture();button(f,'locate').click();const locate=f.actions[0];f.notify();f.doc.tick();f.content.visible=false;assert.equal(locate.current(),true);f.view.pending=undefined;f.content.visible=true;f.view.invoke('openSource');const source=f.actions[1];f.content.visible=false;assert.equal(source.current(),false);});
test('return to board works without a center and survives its own visibility change',async()=>{const f=await fixture();f.view.history.clear();let guard=()=>false;f.host.returnToBoard=(current:()=>boolean)=>{guard=current;};f.view.invoke('returnToBoard');f.content.visible=false;assert.equal(guard(),true);});
test('source actions coalesce double activation while pending',async()=>{const f=await fixture();let calls=0,finish!:()=>void;f.host.openSource=()=>{calls++;return new Promise<void>(resolve=>finish=resolve);};button(f,'source').click();f.view.invoke('openSource');assert.equal(calls,1);assert.equal(button(f,'source').disabled,true);finish();await Promise.resolve();await Promise.resolve();await Promise.resolve();f.doc.tick();assert.equal(button(f,'source').disabled,false);});
test('an old action settlement cannot clear a newer center action',async()=>{const f=await fixture(),finish:(()=>void)[]=[];f.host.openSource=()=>new Promise<void>(resolve=>finish.push(resolve));f.view.invoke('openSource');f.view.setContext('c');f.doc.tick();f.view.invoke('openSource');const token=f.view.pending.token;finish[0]();await Promise.resolve();await Promise.resolve();await Promise.resolve();assert.equal(f.view.pending.token,token);finish[1]();await Promise.resolve();await Promise.resolve();await Promise.resolve();assert.equal(f.view.pending,undefined);});


test('hidden toggle callbacks cannot rebuild graph lines and visible toggles coalesce',async()=>{const f=await fixture(),svg=f.content.querySelector('.ts-local-relations-lines');f.content.visible=false;for(const detail of f.view.groupsHost.querySelectorAll('details'))detail.ontoggle?.();f.doc.tick();assert.equal(f.content.querySelector('.ts-local-relations-lines'),svg);assert.equal(f.doc.frames.size,0);f.content.visible=true;for(const detail of f.view.groupsHost.querySelectorAll('details'))detail.ontoggle?.();assert.equal(f.doc.frames.size,1);f.doc.tick();assert.notEqual(f.content.querySelector('.ts-local-relations-lines'),svg);});
test('relationship evidence exposes real board endpoints labels and named common parents',async()=>{const f=await fixture();const proof=f.content.querySelectorAll('[data-relation-evidence]');assert.equal(proof.length,3);for(const el of proof){el.open=true;el.ontoggle?.();}assert.ok(proof.some(p=>p.textContent.includes('共同父节点：对象 a')));assert.ok(proof.some(p=>p.textContent.includes('对象 b → 对象 d · 理由')));const sibling=proof.find(p=>p.textContent.includes('共同父节点'))!;sibling.open=true;f.notify();f.doc.tick();assert.equal(f.content.querySelectorAll('[data-relation-evidence]').find(p=>p.dataset.relationEvidence===sibling.dataset.relationEvidence)!.open,true);});
test('explicit final source handoff permits its own hide while retaining all context guards',async()=>{const f=await fixture();f.view.invoke('openSource');const guard=f.actions[0].current as (allowHidden?:boolean)=>boolean;assert.equal(guard(true),true);f.content.visible=false;f.notify();assert.equal(guard(),true);assert.equal(guard(true),true);f.view.setContext('c');assert.equal(guard(true),false);});


test('view keyboard shortcuts focus filter clear it and traverse center history',async()=>{const f=await fixture(),search=f.content.querySelector('.ts-local-relations-search')!;const key=(value:string,extra:any={})=>{let prevented=false;f.view.keydown({key:value,defaultPrevented:false,isComposing:false,altKey:false,ctrlKey:false,metaKey:false,shiftKey:false,preventDefault(){prevented=true;},stopPropagation(){},...extra});return prevented;};for(const event of [{key:'F4'},{key:'f',metaKey:true},{key:'f',ctrlKey:true}]){f.doc.activeElement=null;assert.equal(key(event.key,event),true);assert.equal(f.doc.activeElement,search);}search.value='理由';search.oninput?.();f.doc.tick();assert.equal(key('Escape'),true);f.doc.tick();assert.equal(search.value,'');assert.equal(f.doc.activeElement,search);f.view.setContext('a');f.doc.tick();assert.equal(key('ArrowLeft',{altKey:true}),true);f.doc.tick();assert.equal(f.view.history.current,'b');key('ArrowRight',{altKey:true});f.doc.tick();assert.equal(f.view.history.current,'a');assert.equal(key('f',{ctrlKey:true,isComposing:true}),false);assert.equal(key('ArrowLeft',{altKey:true,keyCode:229}),false);});


test('same-ID centers on different boards do not inherit pending actions or stale settlement',async()=>{const f=await fixture(),finish:(()=>void)[]=[];f.host.openSource=()=>new Promise<void>(resolve=>finish.push(resolve));f.view.invoke('openSource');assert.equal(finish.length,1);f.setSnapshot({...f.snapshot,key:{},path:'Other.thoughtspace'});f.notify();f.doc.tick();assert.equal(button(f,'source').disabled,false);f.view.invoke('openSource');assert.equal(finish.length,2);const token=f.view.pending.token;finish[0]();await Promise.resolve();await Promise.resolve();await Promise.resolve();assert.equal(f.view.pending.token,token);assert.equal(button(f,'source').disabled,true);finish[1]();await Promise.resolve();await Promise.resolve();await Promise.resolve();assert.equal(f.view.pending,undefined);});
test('focused relation group summaries retain their native focus and open state on refresh',async()=>{const f=await fixture();for(const kind of f.content.querySelectorAll('.ts-local-relations-group').map(group=>group.dataset.kind)){const key='group:'+kind,summary=f.content.querySelectorAll('summary').find(el=>el.dataset.relationFocus===key)!;summary.parentElement!.open=false;summary.focus();f.notify();f.doc.tick();const next=f.content.querySelectorAll('summary').find(el=>el.dataset.relationFocus===key)!;assert.equal(f.doc.activeElement,next);assert.equal(next.parentElement!.open,false);}});


test('hidden then shown source actions remain cancelled and cannot block a new invocation',async()=>{const f=await fixture(),finish:(()=>void)[]=[],guards:((allowHidden?:boolean)=>boolean)[]=[];f.host.openSource=(_id:string,current:(allowHidden?:boolean)=>boolean)=>{guards.push(current);return new Promise<void>(resolve=>finish.push(resolve));};f.view.invoke('openSource');f.content.visible=false;f.notify();assert.equal(guards[0](),false);f.content.visible=true;f.notify();f.doc.tick();assert.equal(guards[0](),false);assert.equal(guards[0](true),false);f.view.invoke('openSource');const token=f.view.pending.token;finish[0]();await Promise.resolve();await Promise.resolve();await Promise.resolve();assert.equal(f.view.pending.token,token);finish[1]();});
test('a source request cannot commit hidden navigation before a valid visible handoff',async()=>{const f=await fixture();f.view.invoke('openSource');const guard=f.actions[0].current as (allowHidden?:boolean)=>boolean;f.content.visible=false;assert.equal(guard(true),false);});
test('parallel-edge evidence is lazy and its expanded DOM and label preview stay bounded',async()=>{const f=await fixture();for(let i=0;i<1000;i++)f.board.edges.push({id:'parallel-'+i,from:'b',to:'d',label:'长标签'.repeat(100)+i,direction:'forward'});f.notify();f.doc.tick();const proof=f.content.querySelectorAll('[data-relation-evidence]').find(el=>el.dataset.relationEvidence==='evidence:outgoing:d')!;assert.equal(proof.querySelectorAll('div').length,0);assert.ok(f.content.textContent.length<3000);assert.match(proof.textContent,/1001 条/);proof.open=true;proof.ontoggle?.();assert.equal(proof.querySelectorAll('div').length,20);assert.match(proof.textContent,/其余 981 条未列出/);proof.ontoggle?.();assert.equal(proof.querySelectorAll('div').length,20);});

for(const kind of ['card','board','section'] as const)test(`${kind} objects support explicit centering, selection follow, pins and source guards`,async()=>{const f=await fixture(),target=f.board.nodes.find(n=>n.id==='d')!;target.kind=kind;target.x=1000;target.file=kind==='card'?'Notes/D.md':kind==='board'?'Child.thoughtspace':undefined;f.view.setContext('d');f.doc.tick();assert.equal(f.view.history.current,'d');assert.equal(button(f,'pin-center').disabled,false);button(f,'pin-center').click();f.doc.tick();assert.deepEqual(f.view.pins.ids,['d']);f.view.invoke('openSource');assert.equal(f.actions.at(-1)?.current(),true);f.view.setContext('b');f.doc.tick();f.snapshot.selectedId='d';f.notify();f.doc.tick();assert.equal(f.view.history.current,'d');assert.ok(f.content.querySelector('.ts-local-relations-center')!.textContent.includes('对象 d'));});
test('plain text and source-linked text cannot become centers or pins by explicit or follow entry',async()=>{const f=await fixture(),before=f.view.history.current;for(const id of ['h','i']){const target=f.board.nodes.find(n=>n.id===id)!;target.kind='text';target.text='文本 '+id;target.file=id==='i'?'Notes/Source.md':undefined;f.view.setContext(id);f.doc.tick();assert.equal(f.view.history.current,before);f.view.togglePin(id);assert.deepEqual(f.view.pins.ids,[]);f.snapshot.selectedId=id;f.notify();f.doc.tick();assert.equal(f.view.history.current,before);}assert.equal(f.actions.length,0);});
test('changing supported objects into text removes history and pins and invalidates pending actions',async()=>{const f=await fixture();f.view.togglePin('b');f.view.setContext('d');f.doc.tick();f.view.togglePin('d');f.view.invoke('openSource');const guard=f.actions.at(-1)!.current;assert.equal(guard(),true);for(const id of ['b','d'])f.board.nodes.find(n=>n.id===id)!.kind='text';assert.equal(guard(),false);f.notify();f.doc.tick();assert.equal(f.view.history.current,undefined);assert.deepEqual(f.view.pins.ids,[]);assert.equal(button(f,'back').disabled,true);assert.equal(button(f,'forward').disabled,true);assert.equal(f.content.querySelector('.ts-local-relations-search')!.disabled,true);assert.match(f.content.textContent,/文本不参与脑图/);});
test('unsupported historical and fixed IDs reconcile even while selection following is locked',async()=>{const f=await fixture();f.view.setContext('a');f.doc.tick();f.view.togglePin('a');f.view.togglePin('b');f.view.setFollowSelection(false);f.board.nodes.find(n=>n.id==='a')!.kind='text';f.notify();f.doc.tick();assert.equal(f.view.history.current,'b');assert.deepEqual(f.view.pins.ids,['b']);assert.equal(button(f,'forward').disabled,true);});
test('neighbor centering and history reveal their new center while same-center refresh retains scroll',async()=>{const f=await fixture();f.view.groupsHost.scrollTop=900;f.notify();f.doc.tick();assert.equal(f.view.groupsHost.scrollTop,900);button(f,'neighbor:parents:a').click();f.doc.tick();assert.equal(f.view.groupsHost.scrollTop,0);f.view.groupsHost.scrollTop=1200;button(f,'back').click();f.doc.tick();assert.equal(f.view.history.current,'b');assert.equal(f.view.groupsHost.scrollTop,0);});
test('switching board with identical center ID resets old relation scroll',async()=>{const f=await fixture();f.view.groupsHost.scrollTop=900;f.setSnapshot({...f.snapshot,key:{},path:'Other.thoughtspace'});f.notify();f.doc.tick();assert.equal(f.view.groupsHost.scrollTop,0);});
test('wide layout keeps center at the start of tall neighboring columns',()=>{const css=readFileSync('src/local-relations.css','utf8');const wide=css.slice(css.indexOf('@container (min-width:760px)'));assert.match(wide,/\.ts-local-relations-center\{[^}]*align-self:start/);assert.match(wide,/grid-template-areas:'\. parents \.' 'incoming center outgoing' 'associated children siblings'/);});

