test('neighbors without source paths show a readable type while their tooltip retains identity',async()=>{const f=await fixture();for(const kind of ['card','board','section'] as const){const target=f.board.nodes.find(n=>n.id==='d')!;target.kind=kind;delete target.file;f.notify();f.doc.tick();const b=button(f,'neighbor:outgoing:d'),path=b.parentElement!.querySelector('.ts-local-relations-neighbor-path')!;assert.equal(path.textContent,kind==='card'?'笔记卡片':kind==='board'?'子白板':'分组');assert.equal(path.getAttribute('title'),'d');assert.equal(b.title,'d');}f.board.nodes.find(n=>n.id==='d')!.file='Deep/Folder/Long filename.md';f.notify();f.doc.tick();const b=button(f,'neighbor:outgoing:d');assert.equal(b.parentElement!.querySelector('.ts-local-relations-neighbor-path')!.textContent,'Deep/Folder/Long filename.md');assert.equal(b.title,'Deep/Folder/Long filename.md · d');});
test('new centers reset collapsed groups and evidence while same-center refresh retains disclosure',async()=>{const f=await fixture();for(const detail of f.content.querySelectorAll('details'))detail.open=!!detail.dataset.relationEvidence;f.notify();f.doc.tick();assert.ok(f.content.querySelectorAll('details').filter(el=>el.dataset.kind).every(el=>!el.open));f.view.setContext('a');f.doc.tick();assert.ok(f.content.querySelectorAll('details').filter(el=>el.dataset.kind).every(el=>el.open));assert.ok(f.content.querySelectorAll('[data-relation-evidence]').every(el=>!el.open));});
test('dense neighbor text keeps bounded title evidence and single-line paths with native tooltips',()=>{const css=readFileSync('src/local-relations.css','utf8');assert.match(css,/\.ts-local-relations-neighbor-title,[^{]+\.ts-local-relations-evidence\{[^}]*-webkit-line-clamp:2/);assert.match(css,/\.ts-local-relations-neighbor-path\{[^}]*white-space:nowrap;[^}]*text-overflow:ellipsis/);});
for(const [kind,hint] of [['card','此对象暂无本板连线。'],['section','分组成员不会自动成为父子节点。'],['board','子白板内容不会在此递归展开，可打开来源查看。']] as const)test(`${kind} zero-neighbor state explains local scope without implying missing hierarchy`,async()=>{const f=await fixture();f.board.nodes.find(n=>n.id==='h')!.kind=kind;f.view.setContext('h');f.doc.tick();assert.match(f.view.centerHost.textContent,/此对象暂无本板连线/);assert.ok(f.view.centerHost.textContent.includes(hint));assert.match(f.view.counts.textContent,/对象：列出 0 · 关系匹配 0 \/ 共 0/);});
test('native tab activation invalidates a hidden source request without waiting for layout resize',async()=>{const f=await fixture();let guard!:()=>boolean;f.host.openSource=(_id:string,current:()=>boolean)=>{guard=current;return new Promise<void>(()=>{});};f.view.invoke('openSource');assert.equal(guard(),true);f.content.visible=false;const nativeTabChange=f.view.app.workspace.handlers.get('active-leaf-change');assert.ok(nativeTabChange);const before=builds;nativeTabChange();f.doc.tick();assert.equal(builds,before);assert.equal(guard(),false);f.content.visible=true;nativeTabChange();f.doc.tick();assert.equal(guard(),false);assert.equal(button(f,'source').disabled,false);await f.view.onClose();nativeTabChange();assert.equal(f.doc.frames.size,0);});

const findKey=(extra:any={})=>({key:'f',defaultPrevented:false,isComposing:false,keyCode:70,altKey:false,ctrlKey:false,metaKey:true,shiftKey:false,preventDefault(){this.defaultPrevented=true;},stopPropagation(){},...extra});
test('native Obsidian View.scope handles Mod-F before global find can consume DOM keydown',async()=>{const f=await fixture();assert.equal(f.view.scope.parent,f.view.app.scope);assert.equal(f.view.scope.handlers.length,2);const handler=f.view.scope.handlers[0];assert.deepEqual(handler.modifiers,['Mod']);assert.equal(handler.key,'f');button(f,'more-toggle').click();button(f,'follow').focus();const event=findKey({target:button(f,'follow')});assert.equal(handler.func(event),false);assert.equal(event.defaultPrevented,true);assert.equal(f.doc.activeElement,f.content.querySelector('.ts-local-relations-search'));});
for(const reason of ['hidden','other-editor','other-window','disabled-search','closed','composing','legacy-ime','already-prevented'])test(`native find scope preserves default behavior for ${reason}`,async()=>{const f=await fixture();button(f,'more-toggle').click();button(f,'follow').focus();const event=findKey({target:button(f,'follow')});if(reason==='hidden')f.content.visible=false;if(reason==='other-editor'){const other=f.content.parentElement!.createEl('textarea');other.focus();event.target=other;}if(reason==='other-window')event.target=new El('ROOT',new Doc());if(reason==='disabled-search')f.content.querySelector('.ts-local-relations-search')!.disabled=true;if(reason==='closed')await f.view.onClose();if(reason==='composing')event.isComposing=true;if(reason==='legacy-ime')event.keyCode=229;if(reason==='already-prevented')event.defaultPrevented=true;const before=f.doc.activeElement;assert.equal(f.view.scope.handlers[0].func(event),undefined);assert.equal(f.doc.activeElement,before);assert.equal(event.defaultPrevented,reason==='already-prevented');});
test('DOM find fallback leaves modified global-search shortcuts alone',async()=>{const f=await fixture();button(f,'more-toggle').click();button(f,'follow').focus();const event=findKey({shiftKey:true});f.view.keydown(event);assert.equal(event.defaultPrevented,false);assert.equal(f.doc.activeElement,button(f,'follow'));});

test('graph lines ignore rows outside group and outer viewports while retaining partially visible rows',async()=>{const f=await fixture();const neighbors=[button(f,'neighbor:parents:a'),button(f,'neighbor:siblings:c'),button(f,'neighbor:outgoing:d')];const rect=(top:number,bottom:number)=>({left:0,right:100,top,bottom,width:100,height:bottom-top});f.view.groupsHost.getBoundingClientRect=()=>rect(0,100);for(const el of neighbors){el.closest('.ts-local-relations-neighbors')!.getBoundingClientRect=()=>rect(10,80);el.closest('.ts-local-relations-group')!.getBoundingClientRect=()=>rect(0,100);}neighbors[0].getBoundingClientRect=()=>rect(80,110);neighbors[1].getBoundingClientRect=()=>rect(70,95);neighbors[2].getBoundingClientRect=()=>rect(10,30);f.view.drawLinks();assert.equal(f.content.querySelectorAll('[data-kind]').filter(el=>el.tagName==='PATH').length,2);neighbors[2].closest('.ts-local-relations-neighbors')!.getBoundingClientRect=()=>rect(120,160);neighbors[2].getBoundingClientRect=()=>rect(125,150);f.view.drawLinks();assert.equal(f.content.querySelectorAll('[data-kind]').filter(el=>el.tagName==='PATH').length,1);const path=f.content.querySelectorAll('path').find(el=>el.getAttribute('data-kind')==='siblings')!;assert.match(path.getAttribute('d')!,/V 75 H 0$/);});
test('nested and outer scrolling coalesce line redraws without rebuilding neighborhoods or changing counts',async()=>{const f=await fixture(),before=builds,counts=f.view.counts.textContent,svg=f.content.querySelector('.ts-local-relations-lines');const lists=f.content.querySelectorAll('.ts-local-relations-neighbors');for(let i=0;i<5;i++){for(const list of lists)list.onscroll?.();f.view.groupsHost.onscroll();}assert.equal(f.doc.frames.size,1);f.doc.tick();assert.equal(builds,before);assert.equal(f.view.counts.textContent,counts);assert.notEqual(f.content.querySelector('.ts-local-relations-lines'),svg);f.content.visible=false;for(const list of lists)list.onscroll?.();f.view.groupsHost.onscroll();assert.equal(f.doc.frames.size,0);await f.view.onClose();for(const list of lists)list.onscroll?.();assert.equal(f.doc.frames.size,0);});
