test('native find scope handles active-view body focus after tab opening but not another active leaf',async()=>{const f=await fixture();f.doc.body!.focus();const event=findKey({target:f.doc.body});assert.equal(f.view.scope.handlers[0].func(event),false);assert.equal(f.doc.activeElement,f.content.querySelector('.ts-local-relations-search'));f.doc.body!.focus();f.view.app.workspace.activeView=undefined;const other=findKey({target:f.doc.body});assert.equal(f.view.scope.handlers[0].func(other),undefined);assert.equal(other.defaultPrevented,false);assert.equal(f.doc.activeElement,f.doc.body);});
