const settle=async()=>{await Promise.resolve();await Promise.resolve();await Promise.resolve();};
const relationIds=(f:Awaited<ReturnType<typeof fixture>>,kind:string)=>f.content.querySelectorAll('[data-relation-kind]').filter(el=>el.dataset.relationKind===kind).map(el=>el.dataset.relationFocus!.split(':').at(-1));
test('all 37 neighbors remain reachable through bounded per-group pagination without changing board data',async()=>{const f=await fixture();for(let i=0;i<37;i++)f.board.nodes.push(node('page-'+i));f.board.edges=Array.from({length:37},(_,i)=>({id:'edge-'+i,from:'b',to:'page-'+i,label:'',direction:'forward' as const}));const before=JSON.stringify(f.board);f.notify();f.doc.tick();const seen=new Set<string>();for(let page=0;page<4;page++){const ids=relationIds(f,'outgoing');assert.ok(ids.length<=10);ids.forEach(id=>seen.add(id!));assert.match(f.view.counts.textContent,/共 37/);const next=button(f,'page:outgoing:next');assert.equal(next.disabled,page===3);if(!next.disabled){next.click();f.doc.tick();}}assert.equal(seen.size,37);assert.equal(JSON.stringify(f.board),before);assert.equal(f.snapshot.selectedId,'b');});
test('group pagination resets only its own scroll and a new query resets page selection',async()=>{const f=await fixture();for(let i=0;i<25;i++){f.board.nodes.push(node('q-'+i));f.board.edges.push({id:'q-edge-'+i,from:'b',to:'q-'+i,label:'',direction:'forward'});}f.notify();f.doc.tick();const list=(kind:string)=>f.content.querySelectorAll('.ts-local-relations-group').find(el=>el.dataset.kind===kind)!.querySelector('.ts-local-relations-neighbors')!;list('parents').scrollTop=100;list('outgoing').scrollTop=250;button(f,'page:outgoing:next').click();f.doc.tick();assert.equal(list('parents').scrollTop,100);assert.equal(list('outgoing').scrollTop,0);const search=f.content.querySelector('.ts-local-relations-search')!;search.value='q-24';search.oninput?.();f.doc.tick();assert.deepEqual(relationIds(f,'outgoing'),['q-24']);assert.equal(f.view.pages.outgoing,undefined);});
test('board and native evidence after item 20 remain reachable and native evidence preserves source identity',async()=>{const f=await fixture();for(let i=0;i<46;i++)f.board.edges.push({id:'proof-'+i,from:'b',to:'d',label:'proof '+i,direction:'forward'});const evidence=[{id:'native-property',kind:'property',sourcePath:'Notes/B.md',targetPath:'Notes/D.md',subpath:'#Anchor',line:4,property:'related',original:'[[D#Anchor]]'},{id:'native-indexed',kind:'indexed',sourcePath:'Notes/B.md',targetPath:'Notes/D.md',subpath:'',count:7}];f.host.native=()=>({relations:[{nodeId:'d',kind:'outgoing',evidence,evidenceTotal:2}],tagsByNode:new Map(),pendingPaths:[]});let opened:any;f.host.openEvidence=(proof:any,current:()=>boolean)=>{assert.equal(current(),true);opened=proof;};f.notify();f.doc.tick();let proof=f.content.querySelectorAll('[data-relation-evidence]').find(el=>el.dataset.relationEvidence==='evidence:outgoing:d')!;proof.open=true;proof.ontoggle?.();assert.match(proof.textContent,/49 条/);assert.equal(proof.querySelectorAll('[data-evidence-row]').length,20);for(let i=0;i<2;i++){button(f,'proof-page:outgoing:d:next').click();f.doc.tick();}proof=f.content.querySelectorAll('[data-relation-evidence]').find(el=>el.dataset.relationEvidence==='evidence:outgoing:d')!;assert.equal(proof.querySelectorAll('[data-evidence-row]').length,9);assert.match(proof.textContent,/原生索引链接 · 7 次（位置未就绪）/);button(f,'native-evidence:native-property').click();assert.equal(opened,evidence[0]);await settle();});
test('local center picker includes isolated same-title objects by stable ID and excludes text',async()=>{const f=await fixture();f.board.nodes.find(n=>n.id==='h')!.title='相同标题';f.board.nodes.find(n=>n.id==='i')!.title='相同标题';f.board.nodes.push({...node('excluded'),kind:'text',text:'相同标题'});button(f,'center-picker-toggle').click();const input=f.view.pickerSearch;input.value='相同标题';input.oninput();assert.ok(button(f,'center-result:h'));assert.ok(button(f,'center-result:i'));assert.equal(button(f,'center-result:excluded'),undefined);button(f,'center-result:i').click();f.doc.tick();assert.equal(f.view.history.current,'i');assert.equal(f.view.pickerOpen,false);assert.equal(f.snapshot.selectedId,'b');});
test('search arrows focus results and Enter selects without losing native button behavior or IME',async()=>{const f=await fixture(),input=f.content.querySelector('.ts-local-relations-search')!;button(f,'filter-toggle').click();input.focus();const down=findKey({key:'ArrowDown',metaKey:false});f.view.keydown(down);assert.equal(down.defaultPrevented,true);assert.ok(f.doc.activeElement?.dataset.relationKind);const focused=f.doc.activeElement;const enter=findKey({key:'Enter',metaKey:false});f.view.keydown(enter);assert.equal(enter.defaultPrevented,false);assert.equal(f.doc.activeElement,focused);input.focus();const before=f.view.history.current;const ime=findKey({key:'Enter',metaKey:false,isComposing:true});f.view.keydown(ime);assert.equal(ime.defaultPrevented,false);assert.equal(f.view.history.current,before);f.view.keydown(findKey({key:'Enter',metaKey:false}));f.doc.tick();assert.equal(f.view.history.current,'a');});
test('center picker arrows and Enter activate an isolated object and Escape closes only that picker',async()=>{const f=await fixture();button(f,'center-picker-toggle').click();f.view.pickerSearch.value='对象 i';f.view.pickerSearch.oninput();f.view.pickerSearch.focus();const enter=findKey({key:'Enter',metaKey:false});f.view.keydown(enter);f.doc.tick();assert.equal(f.view.history.current,'i');button(f,'center-picker-toggle').click();f.view.keydown(findKey({key:'Escape',metaKey:false}));assert.equal(f.view.pickerOpen,false);assert.equal(f.doc.activeElement,button(f,'center-picker-toggle'));});
test('pending metadata explains incomplete native relations without claiming a complete zero result',async()=>{const f=await fixture();f.board.edges=[];f.host.native=()=>({relations:[],tagsByNode:new Map(),pendingPaths:['Notes/B.md']});f.notify();f.doc.tick();assert.match(f.view.centerHost.textContent,/索引尚未就绪/);assert.doesNotMatch(f.view.centerHost.textContent,/暂无本板连线/);});
test('hidden views never call native metadata while scrolling only redraws existing geometry',async()=>{const f=await fixture();let reads=0;f.host.native=()=>{reads++;return{relations:[],tagsByNode:new Map(),pendingPaths:[]};};f.notify();f.doc.tick();const before=reads;f.content.visible=false;for(let i=0;i<10;i++)f.notify();f.doc.tick();assert.equal(reads,before);f.content.visible=true;f.view.groupsHost.onscroll();f.doc.tick();assert.equal(reads,before);});

test('workspace state round-trip restores true history cursor, pins, MRU and filters independently',async()=>{const f=await fixture();f.view.togglePin('b');f.view.setContext('d');f.view.setContext('a');f.view.travel(false);f.view.query='reason';f.view.saved.settings.density='comfortable';const state=f.view.getState(),copy=await fixture();await copy.view.setState(state);copy.doc.tick();assert.equal(copy.view.history.current,'d');assert.equal(copy.view.history.canForward,true);assert.deepEqual(copy.view.pins.ids,['b']);assert.deepEqual(copy.view.recent,['d','a','b']);assert.equal(copy.view.query,'reason');assert.equal(copy.view.saved.settings.density,'comfortable');copy.view.travel(true);copy.doc.tick();assert.equal(copy.view.history.current,'a');assert.equal(copy.snapshot.selectedId,'b');});
test('fresh normal entry restores saved center without board-follow overwriting it on first refresh',async()=>{const f=await fixture(),saved=relationState.cleanLocalRelationsState({version:1,center:'d',history:{entries:['b','d'],index:1},pins:['a'],recent:['d','b'],follow:'board'});f.host.loadState=()=>saved;f.setSnapshot({...f.snapshot,key:{}});f.view.setContext();f.doc.tick();assert.equal(f.view.history.current,'d');assert.deepEqual(f.view.pins.ids,['a']);f.notify();f.doc.tick();assert.equal(f.view.history.current,'d');f.snapshot.selectedId='a';f.notify();f.doc.tick();assert.equal(f.view.history.current,'a');});
test('real state changes save plugin preferences and request workspace persistence but refresh and scrolling do not',async()=>{const f=await fixture(),saved:any[]=[];f.host.saveState=(path:string,state:any)=>saved.push({path,state});const before=f.view.app.workspace.savedLayouts;f.view.togglePin('b');assert.equal(saved.length,1);assert.equal(saved[0].path,'Board.thoughtspace');assert.ok(f.view.app.workspace.savedLayouts>before);const count=f.view.app.workspace.savedLayouts;for(let i=0;i<4;i++){f.notify();f.doc.tick();f.view.groupsHost.onscroll();f.doc.tick();}assert.equal(saved.length,1);assert.equal(f.view.app.workspace.savedLayouts,count);await f.view.onClose();assert.equal(saved.length,1);});
test('closing an older window after passive reconciliation cannot overwrite another window latest active center',async()=>{const older=await fixture(),newer=await fixture();let saved:any;const save=(_path:string,state:any)=>saved=state;older.host.saveState=save;newer.host.saveState=save;older.view.setFollowSelection(false);older.doc.tick();older.view.togglePin('b');newer.view.setContext('d');newer.doc.tick();assert.equal(saved.center,'d');older.board.nodes=older.board.nodes.filter(node=>node.id!=='b');older.notify();older.doc.tick();await older.view.onClose();assert.equal(saved.center,'d');});
test('pending workspace restore retains its legal target and resumes when the original board arrives later',async()=>{const f=await fixture(),snapshot=f.snapshot,saved=f.view.getState();saved.originLeafId='original-leaf';saved.state.center='d';saved.state.history={entries:['b','d'],index:1};let ready=false,attempts=0;f.setSnapshot(undefined);f.host.restoreContext=async(path:string,origin:string,current:()=>boolean)=>{attempts++;assert.equal(path,'Board.thoughtspace');assert.equal(origin,'original-leaf');return ready&&current();};await f.view.setState(saved);await settle();f.doc.tick();assert.equal(f.view.getState().boardPath,'Board.thoughtspace');assert.equal(f.view.getState().originLeafId,'original-leaf');assert.match(f.content.textContent,/等待原白板加载/);const before=attempts;for(let i=0;i<5;i++)f.doc.tick();assert.equal(attempts,before);ready=true;f.setSnapshot(snapshot);f.notify();await settle();f.doc.tick();assert.equal(f.view.history.current,'d');assert.equal(f.view.pendingWorkspace,undefined);});
test('closing or explicitly rebinding while a workspace restore waits prevents stale restoration',async()=>{for(const action of ['close','rebind']){const f=await fixture(),state=f.view.getState();state.state.center='d';state.state.history={entries:['d'],index:0};let finish!:()=>void,guard!:()=>boolean;f.host.restoreContext=(_path:string,_origin:string,current:()=>boolean)=>{guard=current;return new Promise<boolean>(resolve=>finish=()=>resolve(true));};const restoring=f.view.setState(state);if(action==='close')await f.view.onClose();else f.view.setContext('a');finish();await restoring;assert.equal(guard(),false);if(action==='rebind')assert.equal(f.view.history.current,'a');else assert.equal(f.content.children.length,0);}});
test('recent strip remains deduplicated and bounded to 14 while true back/forward branching remains independent',async()=>{const f=await fixture();for(let i=0;i<20;i++){f.board.nodes.push(node('recent-'+i));f.view.setContext('recent-'+i);}f.doc.tick();assert.equal(f.view.recentHost.querySelector('.ts-local-relations-recent-list').querySelectorAll('button').length,14);f.view.travel(false);f.view.setContext('a');f.doc.tick();assert.equal(f.view.history.canForward,false);assert.ok(f.view.recent.includes('recent-19'));assert.equal(new Set(f.view.recent).size,f.view.recent.length);assert.equal(f.view.recent[0],'a');});
test('note follow keeps the current duplicate-source card and jumps only to a unique matched object',async()=>{const f=await fixture();let active:any={ids:['b','d'],ambiguous:true};f.host.activeSource=()=>active;f.view.setFollow('note');f.doc.tick();assert.equal(f.view.history.current,'b');active={id:'d',ids:['d']};f.notify();f.doc.tick();assert.equal(f.view.history.current,'d');f.snapshot.selectedId='a';f.notify();f.doc.tick();assert.equal(f.view.history.current,'d');f.view.setFollow('locked');active={id:'a',ids:['a']};f.notify();f.doc.tick();assert.equal(f.view.history.current,'d');});
test('explicit companion activation works before a partner leaf exists and then syncs once per center without board mutation',async()=>{const f=await fixture(),before=JSON.stringify(f.board);let enabled=false;const synced:string[]=[];f.host.companion=()=>({enabled,available:false});f.host.setCompanion=(value:boolean)=>enabled=value;f.host.syncSource=(id:string,current:()=>boolean)=>{assert.equal(current(),true);synced.push(id);};f.notify();f.doc.tick();assert.equal(button(f,'companion').disabled,false);button(f,'companion').click();f.doc.tick();await settle();f.doc.tick();assert.deepEqual(synced,['b']);for(let i=0;i<3;i++){f.notify();f.doc.tick();}assert.deepEqual(synced,['b']);f.view.setContext('d');f.doc.tick();await settle();f.doc.tick();assert.deepEqual(synced,['b','d']);button(f,'companion').click();f.doc.tick();f.view.setContext('a');f.doc.tick();assert.deepEqual(synced,['b','d']);assert.equal(JSON.stringify(f.board),before);assert.equal(f.snapshot.selectedId,'b');});
test('non-Markdown sources cannot enable editing or a partner but an active partner switch remains available to disable',async()=>{const f=await fixture();let enabled=false;f.host.source=()=>({label:'子白板',path:'Child.thoughtspace',available:true,canExplain:false});f.host.companion=()=>({enabled,available:false});f.host.setCompanion=(value:boolean)=>enabled=value;f.host.editSource=()=>{};f.notify();f.doc.tick();assert.equal(button(f,'edit-source').disabled,true);assert.equal(button(f,'companion').disabled,true);enabled=true;f.notify();f.doc.tick();assert.equal(button(f,'companion').disabled,false);button(f,'companion').click();assert.equal(enabled,false);});
