const headingTree=(count=70)=>headings.localHeadingTree({kind:'card',path:'Notes/B.md',mtime:100,available:true,metadata:{headings:Array.from({length:count},(_,i)=>({heading:i===0?'父标题':i===1?'深层同名标题':'标题 '+i,level:i===0?1:i===1?3:2,position:{start:{line:i*2,col:0,offset:i*20}}}))}});
async function headingFixture(count=70){const f=await fixture();let tree=headingTree(count);f.host.headings=()=>tree;f.host.openHeading=()=>{};f.notify();f.doc.tick();return{...f,get tree(){return tree;},setTree(next:ReturnType<typeof headingTree>){tree=next;}};}
const disclose=(el:El,open=true)=>{if(open&&el.hidden&&el.classes.has('ts-local-heading-section')){let root=el;while(root.parentElement)root=root.parentElement;root.querySelectorAll('[data-relation-focus]').find(item=>item.dataset.relationFocus==='heading-jump')?.click();}el.open=open;el.ontoggle?.();};
