test('pending expanded native metadata is explained independently from complete board-only second layer',async()=>{const f=await depthFixture();f.host.native=(id:string)=>({relations:[],tagsByNode:new Map(),pendingPaths:id==='d'?['Notes/D.md']:[]});button(f,'depth-expand:outgoing:d').click();assert.match(f.view.depthBody.textContent,/部分第二层来源索引尚未就绪/);assert.equal(f.content.querySelectorAll('[data-depth-target]').length,2);});
for(const reason of ['source-fold','first-page','filter','depth-page','center','hidden'])test(`second-layer native source navigation remains cancelled after ${reason}`,async()=>{const f=await depthFixture();for(let i=0;i<20;i++){f.board.nodes.push(node('late-'+i));f.board.edges.push({id:'late-first-'+i,from:'b',to:'late-'+i,label:'',direction:'forward'});f.board.nodes.push(node('sub-'+i));f.board.edges.push({id:'late-second-'+i,from:'d',to:'sub-'+i,label:'',direction:'forward'});}const proof={id:'guarded-native',kind:'link',sourcePath:'Notes/D.md',targetPath:'Notes/E.md',subpath:''};f.host.native=(id:string)=>({relations:id==='d'?[{nodeId:'e',kind:'outgoing',evidence:[proof],evidenceTotal:1}]:[],tagsByNode:new Map()});let current!:()=>boolean;f.host.openEvidence=(_e:any,guard:()=>boolean)=>{current=guard;return new Promise(()=>{});};f.notify();f.doc.tick();button(f,'depth-expand:outgoing:d').click();disclose(f.content.querySelectorAll('[data-depth-proof]').find(el=>el.dataset.depthProof==='e')!);button(f,'depth-native-evidence:'+JSON.stringify(['e','d','outgoing','guarded-native'])).click();assert.equal(current(),true);if(reason==='source-fold')disclose(f.content.querySelectorAll('.ts-local-relations-group').find(el=>el.dataset.kind==='outgoing')!,false);if(reason==='first-page'){button(f,'page:outgoing:next').click();f.doc.tick();}if(reason==='filter'){f.view.query='absent';f.view.filterChanged();f.doc.tick();}if(reason==='depth-page')button(f,'depth-page:d:next').click();if(reason==='center')f.view.setContext('a');if(reason==='hidden'){f.content.visible=false;f.notify();}assert.equal(current(),false);if(reason==='hidden'){f.content.visible=true;f.notify();f.doc.tick();assert.equal(current(),false);}});

test('shared native evidence uses collision-free via identity and refresh retains the exact source keyboard focus',async()=>{const f=await depthFixture(),evidence={id:'same:proof',kind:'link',sourcePath:'Notes/Shared.md',targetPath:'Notes/E.md',subpath:''};f.host.native=(id:string)=>({relations:['c','d'].includes(id)?[{nodeId:'e',kind:'outgoing',evidence:[evidence],evidenceTotal:1}]:[],tagsByNode:new Map()});f.host.openEvidence=()=>{};f.notify();f.doc.tick();button(f,'depth-expand:outgoing:d').click();button(f,'depth-expand:siblings:c').click();disclose(f.content.querySelectorAll('[data-depth-proof]').find(el=>el.dataset.depthProof==='e')!);const first='depth-native-evidence:'+JSON.stringify(['e','d','outgoing','same:proof']),second='depth-native-evidence:'+JSON.stringify(['e','c','outgoing','same:proof']);assert.ok(button(f,first));assert.ok(button(f,second));assert.notEqual(first,second);button(f,second).focus();f.notify();f.doc.tick();assert.equal(f.doc.activeElement?.dataset.relationFocus,second);assert.equal(f.doc.activeElement?.isConnected,true);assert.equal(f.content.querySelectorAll('[data-relation-focus]').filter(el=>el.dataset.relationFocus===second).length,1);});

test('second-layer return keys distinguish colon-bearing IDs and restore the exact focused source-target pair',async()=>{const f=await fixture();f.board.nodes=['b','a:b','c','a','b:c'].map(node);f.board.edges=[...['a:b','c','a','b:c'].map((id,i)=>({id:'first-'+i,from:'b',to:id,label:'',direction:'forward' as const})),{id:'route-one',from:'a:b',to:'c',label:'',direction:'forward'},{id:'route-two',from:'a',to:'b:c',label:'',direction:'forward'}];f.notify();f.doc.tick();button(f,'depth-expand:outgoing:a:b').click();button(f,'depth-expand:outgoing:a').click();const first='depth-return:'+JSON.stringify(['a:b','c']),second='depth-return:'+JSON.stringify(['a','b:c']);assert.notEqual(first,second);assert.ok(button(f,first));assert.ok(button(f,second));button(f,second).focus();f.notify();f.doc.tick();assert.equal(f.doc.activeElement?.dataset.relationFocus,second);assert.equal(f.doc.activeElement?.closest('.ts-local-depth-branch')?.dataset.depthSourceGroup,'a');assert.equal(f.content.querySelectorAll('[data-relation-focus]').filter(el=>el.dataset.relationFocus===second).length,1);button(f,second).click();f.doc.tick();assert.equal(f.view.history.current,'b:c');assert.equal(f.snapshot.selectedId,'b');});
test('sub-360px split fallback keeps the center in scroll flow and preserves the explicit return control',async()=>{const css=readFileSync('src/local-relations.css','utf8');assert.match(css,/@container \(max-width:359px\)\{\.ts-local-relations-center\{position:relative;top:auto;z-index:1\}\}/);assert.match(css,/@container \(max-width:759px\)\{[^\n]*\.ts-local-relations-center\{position:sticky;top:2px;z-index:3\}/);assert.match(css,/\.ts-local-relations\{overflow-y:auto\}/);const f=await fixture();f.content.clientWidth=190;const state=JSON.stringify(f.view.getState());let returned=0;f.view.centerHost.scrollIntoView=()=>returned++;button(f,'return-center').click();assert.equal(returned,1);assert.equal(button(f,'source').disabled,false);assert.equal(button(f,'locate').disabled,false);assert.equal(JSON.stringify(f.view.getState()),state);});
for(const kind of ['board','native-editor'])test(`background graph refresh cannot reclaim ${kind} ownership from a stale graph DOM button`,async()=>{const f=await fixture(),target=new ItemView({contentEl:f.content.parentElement!.createDiv()});button(f,'more-toggle').click();button(f,'follow').focus();const stale=f.doc.activeElement;f.view.app.workspace.activeView=target;assert.equal(f.doc.activeElement,stale);for(let i=0;i<3;i++){f.notify();f.doc.tick();assert.equal(f.view.app.workspace.activeView,target);assert.equal(f.content.contains(f.doc.activeElement),false);}assert.equal(f.doc.activeElement,null);});
