async function editableFixture(){const f=await fixture(),requests:any[]=[];f.board.version=3;for(const item of f.board.nodes)item.file='Notes/'+item.id+'.md';let serial=0,available=true,reason='';f.host.relationEditing=()=>({available,reason});f.host.editRelation=async(command:relationEdit.LocalRelationMutation,current:()=>boolean)=>{if(!current())return{changed:false};requests.push(command);const result=relationEdit.planLocalRelationEdit(f.board,command,'ui-created-'+(++serial));f.board.edges=result.board.edges;f.board.version=result.board.version;f.notify();return{changed:result.changed,edgeId:result.edgeId};};f.notify();f.doc.tick();return{...f,requests,setAvailability(value:boolean,message=''){available=value;reason=message;}};}
const selectRelationTarget=(f:Awaited<ReturnType<typeof editableFixture>>,id:string)=>{const change=button(f,'relation-target-change');if(change&&!change.hidden)change.click();button(f,'relation-target:'+JSON.stringify(id)).click();};
const setRelationField=(f:{content:El},key:string,value:string)=>{const field=button(f,key) as any;field.value=value;if(key==='relation-label')field.oninput();else field.onchange();};
