test('new relations select supported board targets and preserve geometry native source strings selection and view state',async()=>{const f=await editableFixture();f.board.nodes.find(n=>n.id==='e')!.kind='section';f.board.nodes.push({...node('excluded'),kind:'text',text:'excluded'});const geometry=JSON.stringify(f.board.nodes),viewport=JSON.stringify(f.board.viewport),state=JSON.stringify(f.view.getState());button(f,'relation-edit-open').click();button(f,'relation-new').click();assert.equal(button(f,'relation-save').disabled,true);assert.equal(button(f,'relation-target:'+JSON.stringify('b')),undefined);assert.equal(button(f,'relation-target:'+JSON.stringify('excluded')),undefined);selectRelationTarget(f,'e');setRelationField(f,'relation-label',' 新关联 ');setRelationField(f,'relation-direction','both');button(f,'relation-save').click();await settle();f.doc.tick();assert.equal(f.requests.length,1);const edge=f.board.edges.find(edge=>edge.id==='ui-created-1')!;assert.equal(edge.from,'b');assert.equal(edge.to,'e');assert.equal(edge.label,'新关联');assert.equal(edge.direction,'both');assert.equal(JSON.stringify(f.board.nodes),geometry);assert.equal(JSON.stringify(f.board.viewport),viewport);assert.equal(JSON.stringify(f.view.getState()),state);assert.equal(f.snapshot.selectedId,'b');assert.match(f.view.relationEditorStatus.textContent,/已更新/);});
