test('remove confirmation names one concrete edge and cancellation does not delete parallel edges',async()=>{const f=await editableFixture();f.board.edges.push({id:'parallel',from:'b',to:'d',label:'第二条',direction:'forward'});const before=JSON.stringify(f.board);button(f,'relation-edit-open').click();button(f,'relation-edge:'+JSON.stringify('parallel')).click();button(f,'relation-remove').click();assert.match(f.view.relationConfirmation.textContent,/连线 ID：parallel/);assert.match(f.view.relationConfirmation.textContent,/笔记、卡片和原生引用不会删除/);button(f,'relation-remove-cancel').click();assert.equal(f.requests.length,0);assert.equal(JSON.stringify(f.board),before);button(f,'relation-remove').click();button(f,'relation-remove-confirm').click();await settle();assert.equal(f.requests[0].action,'remove');assert.equal(f.requests[0].edgeId,'parallel');assert.ok(f.board.edges.some(edge=>edge.id==='bd'));assert.equal(f.board.edges.some(edge=>edge.id==='parallel'),false);});
