test('post-commit disk failure retains an explicit warning and never invites duplicate submission',async()=>{const f=await editableFixture();f.host.editRelation=async(command:relationEdit.LocalRelationMutation)=>{const plan=relationEdit.planLocalRelationEdit(f.board,command,'committed');f.board.edges=plan.board.edges;f.setAvailability(false,'保存失败，白板草稿已保留');throw new relationEdit.LocalRelationEditSaveError('磁盘写入失败');};button(f,'relation-edit-open').click();button(f,'relation-new').click();selectRelationTarget(f,'e');button(f,'relation-save').click();await settle();f.doc.tick();assert.ok(f.board.edges.some(edge=>edge.id==='committed'));assert.equal(f.view.relationDraft,undefined);assert.equal(button(f,'relation-new').disabled,true);assert.match(f.view.relationMessage,/操作已应用到白板内存，保存尚未完成/);assert.match(f.view.relationEditorStatus.textContent,/保存失败/);});
for(const reason of ['cancel','close-panel','hide-show','center-roundtrip','board','window','close-view'])test(`pending relation mutation becomes permanently invalid after ${reason}`,async()=>{const f=await editableFixture();let current!:()=>boolean,finish!:(value:relationEdit.LocalRelationEditResult)=>void;f.host.editRelation=(_command:any,guard:()=>boolean)=>{current=guard;return new Promise<relationEdit.LocalRelationEditResult>(resolve=>finish=resolve);};button(f,'relation-edit-open').click();button(f,'relation-new').click();selectRelationTarget(f,'e');button(f,'relation-save').click();assert.equal(current(),true);assert.match(f.view.relationEditorStatus.textContent,/正在提交/);assert.equal(button(f,'relation-save').disabled,true);if(reason==='cancel')button(f,'relation-cancel').click();if(reason==='close-panel')button(f,'relation-editor-close').click();if(reason==='hide-show'){f.content.visible=false;f.notify();f.content.visible=true;f.notify();f.doc.tick();}if(reason==='center-roundtrip'){f.view.setContext('a');f.view.setContext('b');}if(reason==='board')f.setSnapshot({...f.snapshot,key:{}});if(reason==='window')Object.defineProperty(f.content,'ownerDocument',{value:new Doc()});if(reason==='close-view')await f.view.onClose();assert.equal(current(),false);finish({changed:false});await settle();assert.equal(f.board.edges.length,3);});
test('edge and target lists remain bounded while all supported choices are reachable by pagination',async()=>{const f=await editableFixture();for(let i=0;i<25;i++){f.board.nodes.push(node('edit-'+i));f.board.edges.push({id:'edit-edge-'+i,from:'b',to:'edit-'+i,label:'',direction:'forward'});}button(f,'relation-edit-open').click();const edges=new Set<string>();for(let page=0;page<4;page++){const rows=f.content.querySelectorAll('[data-edit-edge]');assert.ok(rows.length<=8);rows.forEach(row=>edges.add(row.dataset.editEdge!));const next=button(f,'relation-edge-page:next');if(!next.disabled)next.click();}assert.equal(edges.size,27);button(f,'relation-new').click();const targets=new Set<string>();for(let page=0;page<5;page++){const rows=f.view.relationTargetResults.querySelectorAll('[data-relation-focus]').filter((el:El)=>el.dataset.relationFocus?.startsWith('relation-target:'));assert.ok(rows.length<=8);rows.forEach((el:El)=>targets.add(JSON.parse(el.dataset.relationFocus!.slice('relation-target:'.length))));const next=button(f,'relation-target-page:next');if(!next.disabled)next.click();}assert.equal(targets.size,33);});
