for(const field of ['input','select','textarea','contenteditable'])test(`relation editor preserves native Alt-arrow editing in ${field} without losing an unsaved draft`,async()=>{const f=await editableFixture();f.view.setContext('a');f.view.setContext('b');f.doc.tick();button(f,'relation-edit-open').click();button(f,'relation-edge:'+JSON.stringify('bd')).click();setRelationField(f,'relation-label','未保存标签');let target:El;if(field==='input')target=button(f,'relation-label');else if(field==='select')target=button(f,'relation-kind');else if(field==='textarea')target=f.view.relationForm.createEl('textarea');else target=f.view.relationForm.createDiv({attr:{contenteditable:'true'}}).createSpan();target.focus();const draft=f.view.relationDraft;for(const key of ['ArrowLeft','ArrowRight']){const event=findKey({key,altKey:true,metaKey:false,target});f.view.keydown(event);assert.equal(event.defaultPrevented,false);f.doc.tick();assert.equal(f.view.history.current,'b');assert.equal(f.view.relationEditorDetails.open,true);assert.equal(f.view.relationDraft,draft);assert.equal(button(f,'relation-label').value,'未保存标签');assert.equal(f.doc.activeElement,target);}assert.equal(f.requests.length,0);});

