test('closing or hiding during identity motion cancels it and a delayed completion cannot redraw',async()=>{for(const close of [false,true]){const f=await fixture();let finish!:()=>void,cancels=0;f.view.motion={capture:()=>({}),cancel:()=>cancels++,play:(_root:unknown,_snapshot:unknown,callback:()=>void)=>finish=callback};f.view.setContext('a');f.doc.tick();const svg=f.content.querySelector('.ts-local-relations-lines');if(close)await f.view.onClose();else{f.content.visible=false;f.notify();}assert.ok(cancels>0);finish();assert.equal(f.view.motionActive,false);assert.equal(f.content.querySelector('.ts-local-relations-lines'),close?undefined:svg);}});

