for(const collapse of ['proof','group'])test(`native evidence remains valid through normal refresh but ${collapse} close/reopen permanently cancels its own request`,async()=>{const f=await fixture();f.host.native=()=>({relations:[{nodeId:'d',kind:'outgoing',evidence:[{id:'one',kind:'link',sourcePath:'B.md',targetPath:'D.md',subpath:'',line:3}],evidenceTotal:1}],tagsByNode:new Map(),pendingPaths:[]});let current!:()=>boolean;f.host.openEvidence=(_evidence:unknown,guard:()=>boolean)=>{current=guard;return new Promise(()=>{});};f.notify();f.doc.tick();const proof=()=>f.content.querySelectorAll('[data-relation-evidence]').find(el=>el.dataset.relationEvidence==='evidence:outgoing:d')!;disclose(proof());button(f,'native-evidence:one').click();assert.equal(current(),true);f.doc.tick();assert.equal(current(),true);const other=f.content.querySelectorAll('[data-relation-evidence]').find(el=>el.dataset.relationEvidence==='evidence:parents:a')!;disclose(other);disclose(other,false);assert.equal(current(),true);const target=collapse==='proof'?proof():proof().closest('.ts-local-relations-group')!;disclose(target,false);assert.equal(current(),false);disclose(target);assert.equal(current(),false);f.notify();f.doc.tick();assert.equal(current(),false);});

test('closed native details cannot leave connector paths or keyboard results even when descendant layout boxes remain',async()=>{const f=await fixture(),parent=button(f,'neighbor:parents:a'),outgoing=button(f,'neighbor:outgoing:d');assert.ok(parent.getClientRects().length);assert.ok(outgoing.getClientRects().length);disclose(parent.closest('.ts-local-relations-group')!,false);disclose(outgoing.closest('.ts-local-relations-group')!,false);f.doc.tick();assert.deepEqual(f.content.querySelectorAll('path').filter(el=>el.dataset.kind).map(el=>el.dataset.kind),['siblings']);const input=f.content.querySelector('.ts-local-relations-search')!;input.focus();f.view.keydown(findKey({key:'ArrowDown',metaKey:false}));assert.equal(f.doc.activeElement,button(f,'neighbor:siblings:c'));input.focus();f.view.keydown(findKey({key:'Enter',metaKey:false}));f.doc.tick();assert.equal(f.view.history.current,'c');});

test('narrow stacked children route through the left gutter without vertical curves through earlier pills',async()=>{const f=await fixture();f.view.setContext('a');f.doc.tick();f.view.groupsHost.getBoundingClientRect=()=>({left:0,top:0,width:320,height:600,right:320,bottom:600});f.view.centerHost.querySelector('h3').getBoundingClientRect=()=>({left:110,top:100,width:100,height:36,right:210,bottom:136});for(const [index,id]of ['b','c'].entries()){const child=button(f,'neighbor:children:'+id);child.getBoundingClientRect=()=>({left:110,top:200+index*50,width:100,height:28,right:210,bottom:228+index*50});for(const cls of ['.ts-local-relations-neighbors','.ts-local-relations-group'])child.closest(cls)!.getBoundingClientRect=()=>({left:0,top:180,width:320,height:150,right:320,bottom:330});}f.view.drawLinks();assert.deepEqual(f.content.querySelectorAll('path').filter(el=>el.dataset.kind==='children').map(el=>el.getAttribute('d')),['M 110 118 H 3 V 214 H 110','M 110 118 H 3 V 264 H 110']);const css=readFileSync('src/local-relations.css','utf8');assert.match(css,/\.ts-local-relations-center>button\{transform:translateY\(28px\)\}/);assert.match(css,/\.ts-local-center-info:not\(\[open\]\)\{transform:translateY\(28px\)\}/);});

test('compatibility view keeps one toolbar with inline search and a compact recent row while advanced tools stay hidden',async()=>{const f=await editableFixture();f.host.returnToBoard=()=>{};f.notify();f.doc.tick();assert.equal(f.view.getDisplayText(),'独立关系浏览');assert.deepEqual(f.view.toolbar.querySelectorAll('[data-relation-focus]').map((el:El)=>el.dataset.relationFocus),['return','back','forward','relation-search','center-picker-toggle','filter-toggle','more-toggle']);assert.ok(f.view.search.parentElement===f.view.toolbar);assert.equal(f.view.search.hidden,false);assert.equal(f.view.filterPanel.hidden,true);assert.equal(f.view.morePanel.hidden,true);assert.equal(f.view.inspectorsHost.hidden,true);assert.equal(f.view.recentHost.hidden,false);assert.equal(f.view.recentHost.querySelector('small'),undefined);assert.equal(f.view.filterPanel.contains(f.view.search),false);assert.equal(f.view.filterPanel.contains(f.view.counts),true);assert.equal(f.view.filterPanel.contains(f.view.optionsHost),true);assert.equal(f.view.secondaryToolbar.contains(button(f,'relation-edit-open')),true);});
test('center keeps source opening visible while secondary native actions live in explicit center details',async()=>{const f=await editableFixture();f.host.editCenter=()=>{};f.notify();f.doc.tick();const info=f.view.centerHost.querySelector('.ts-local-center-info')!,open=button(f,'source');assert.equal(info.open,false);assert.equal(info.contains(open),false);assert.equal(f.view.centerHost.querySelector('.ts-local-relations-center-actions')!.contains(open),true);assert.equal(info.contains(button(f,'edit-source')),true);assert.equal(info.contains(button(f,'locate')),true);assert.equal(info.contains(button(f,'explain')),true);assert.equal(open.disabled,false);open.click();assert.equal(f.actions[0].action,'openSource');});
