test('find shortcuts focus inline search without opening advanced filters and the advanced toggle remains independent',async()=>{const f=await fixture();for(const event of [findKey(),findKey({key:'F4',metaKey:false})]){f.view.keydown(event);assert.equal(f.view.filterPanel.hidden,true);assert.equal(button(f,'filter-toggle').getAttribute('aria-expanded'),'false');assert.ok(f.doc.activeElement===f.view.search);}button(f,'filter-toggle').click();button(f,'query-field').focus();f.view.keydown(findKey({key:'Escape',metaKey:false}));assert.equal(f.view.filterPanel.hidden,true);assert.equal(f.view.search.hidden,false);assert.equal(f.doc.activeElement?.dataset.relationFocus,'filter-toggle');});
