test('Escape in more preserves the inline query before a second Escape clears the visible input',async()=>{const f=await fixture();f.view.search.value='理由';f.view.search.oninput();f.doc.tick();button(f,'more-toggle').click();button(f,'return-center').focus();let hiddenFocusRequests=0;const searchFocus=f.view.search.focus.bind(f.view.search);f.view.search.focus=()=>{if(f.view.search.hidden)hiddenFocusRequests++;searchFocus();};f.view.keydown(findKey({key:'Escape',metaKey:false}));f.doc.tick();assert.equal(f.view.morePanel.hidden,true);assert.equal(f.view.filterPanel.hidden,true);assert.equal(f.view.query,'理由');assert.equal(f.view.search.value,'理由');assert.equal(hiddenFocusRequests,0);assert.equal(f.doc.activeElement?.dataset.relationFocus,'more-toggle');assert.equal(button(f,'filter-toggle').getAttribute('aria-pressed'),'true');f.view.keydown(findKey({key:'Escape',metaKey:false}));assert.equal(f.view.query,'');assert.equal(hiddenFocusRequests,0);assert.ok(f.doc.activeElement===f.view.search);});
test('advanced filters close independently without hiding or clearing the inline search',async()=>{const f=await fixture();f.view.search.value='理由';f.view.search.oninput();f.doc.tick();button(f,'filter-toggle').click();button(f,'query-field').focus();f.view.keydown(findKey({key:'Escape',metaKey:false}));assert.equal(f.view.filterPanel.hidden,true);assert.equal(f.view.search.hidden,false);assert.equal(f.view.query,'理由');assert.equal(f.doc.activeElement?.dataset.relationFocus,'filter-toggle');f.view.search.focus();f.view.keydown(findKey({key:'Escape',metaKey:false}));f.doc.tick();assert.equal(f.view.query,'');assert.equal(f.view.filterPanel.hidden,true);assert.ok(f.doc.activeElement===f.view.search);});
test('more can reopen the compact recent row and recent-close returns keyboard focus to a visible button',async()=>{const f=await fixture();button(f,'recent-close').click();button(f,'more-toggle').click();button(f,'recent-toggle').focus();button(f,'recent-toggle').click();assert.equal(f.view.morePanel.hidden,true);assert.equal(f.view.recentHost.hidden,false);assert.equal(f.doc.activeElement?.dataset.relationFocus,'more-toggle');button(f,'recent-close').focus();button(f,'recent-close').click();assert.equal(f.view.recentHost.hidden,true);assert.equal(f.doc.activeElement?.dataset.relationFocus,'more-toggle');f.notify();f.doc.tick();assert.equal(f.doc.activeElement?.dataset.relationFocus,'more-toggle');});
test('closing a disclosure cannot reclaim focus after another native leaf becomes active',async()=>{const f=await fixture();button(f,'more-toggle').click();button(f,'follow').focus();const old=f.doc.activeElement,other=new ItemView({contentEl:f.content.parentElement!.createDiv()});f.view.app.workspace.activeView=other;f.view.showMore(false);assert.ok(f.doc.activeElement===old);assert.equal(f.view.app.workspace.activeView,other);});
