test('headings are opened from more and close-tool cancels pending navigation without removing content capability',async()=>{const f=await headingFixture(3);let guard!:()=>boolean;f.host.openHeading=(_id:string,_target:unknown,current:()=>boolean)=>{guard=current;return new Promise(()=>{});};button(f,'more-toggle').click();button(f,'heading-jump').click();assert.equal(f.view.morePanel.hidden,true);assert.equal(f.view.inspectorsHost.hidden,false);assert.equal(f.view.depthDetails.hidden,true);assert.equal(f.view.relationEditorDetails.hidden,true);button(f,'heading-open:'+f.tree.items[0].id).click();assert.equal(guard(),true);button(f,'inspectors-close').focus();button(f,'inspectors-close').click();assert.equal(guard(),false);assert.equal(f.view.inspectorsHost.hidden,true);assert.equal(f.doc.activeElement?.dataset.relationFocus,'more-toggle');button(f,'more-toggle').click();button(f,'heading-jump').click();assert.equal(f.view.headingRows.querySelectorAll('[data-heading-id]').length,3);});
test('one entity retains all board directions and native evidence even when an alternate role is on another page',async()=>{const f=await fixture();f.board.edges.push({id:'ba',from:'b',to:'a',label:'逆向引用'},{id:'ab-normal',from:'a',to:'b',label:'普通入向'});for(let i=0;i<24;i++){f.board.nodes.push(node('role-'+i));f.board.edges.push({id:'role-edge-'+i,from:'b',to:'role-'+i,label:''});}const proof={id:'native-a',kind:'link',sourcePath:'B.md',targetPath:'A.md',subpath:'#标题',line:4};f.host.native=()=>({relations:[{nodeId:'a',kind:'outgoing',evidence:[proof],evidenceTotal:1}],tagsByNode:new Map()});f.host.openEvidence=()=>{};f.view.pages.outgoing=1;f.notify();f.doc.tick();assert.equal(f.content.querySelectorAll('[data-relation-motion-id]').filter(el=>el.dataset.relationMotionId==='a').length,1);const detail=button(f,'neighbor:parents:a').parentElement!.querySelector('[data-relation-evidence]')!;disclose(detail);assert.equal(detail.querySelectorAll('[data-evidence-row="board"]').length,3);assert.equal(detail.querySelectorAll('[data-evidence-row="native"]').length,1);assert.match(detail.textContent,/逆向引用/);assert.match(detail.textContent,/普通入向/);assert.match(detail.textContent,/父节点、指向这里、从这里指向/);assert.ok(button(f,'native-evidence:native-a'));});
test('deduplicated multiple-role pagination keeps every object reachable and every multi-page group accessible',async()=>{const f=await fixture();f.board.edges=[];for(let i=0;i<45;i++){const id='paging-'+i;f.board.nodes.push(node(id));if(i<15)f.board.edges.push({id:'branch-'+i,from:'b',to:id,label:'',kind:'branch'});if(i>=5&&i<25)f.board.edges.push({id:'assoc-'+i,from:'b',to:id,label:'',direction:'both'});if(i>=8&&i<38)f.board.edges.push({id:'incoming-'+i,from:id,to:'b',label:''});if(i>=15)f.board.edges.push({id:'outgoing-'+i,from:'b',to:id,label:''});}const before=JSON.stringify(f.board),seen=new Set<string>();for(let a=0;a<2;a++)for(let b=0;b<2;b++)for(let c=0;c<3;c++)for(let d=0;d<3;d++){f.view.pages={children:a,associated:b,incoming:c,outgoing:d};f.notify();f.doc.tick();const ids=f.content.querySelectorAll('[data-relation-kind]').map(el=>el.dataset.relationMotionId);assert.equal(ids.length,new Set(ids).size);assert.ok(ids.length<=60);ids.forEach(id=>seen.add(id));for(const kind of ['children','associated','incoming','outgoing'])assert.ok(button(f,'page:'+kind+':next'));}assert.equal(seen.size,45);assert.equal(JSON.stringify(f.board),before);});
test('toolbar repaint never removes the inline input while filtering or composing',async()=>{const f=await fixture(),search=f.view.search,toolbar=f.view.toolbar;let inputDetached=0;const empty=toolbar.empty.bind(toolbar);toolbar.empty=()=>{if(toolbar.contains(search))inputDetached++;empty();};search.focus();search.value='理由';search.selectionStart=0;search.selectionEnd=1;search.oninput();f.doc.tick();for(let i=0;i<3;i++){f.notify();f.doc.tick();assert.ok(search.parentElement===toolbar);assert.ok(f.view.search===search);assert.ok(f.doc.activeElement===search);assert.equal(search.value,'理由');assert.equal(search.selectionStart,0);assert.equal(search.selectionEnd,1);}const composition=findKey({key:'Escape',metaKey:false,isComposing:true});f.view.keydown(composition);assert.equal(f.view.query,'理由');assert.equal(composition.defaultPrevented,false);assert.equal(inputDetached,0);});
test('toolbar popovers are exclusive and the picker leaves only one visible search input',async()=>{const f=await fixture(),search=f.view.search;button(f,'filter-toggle').click();assert.equal(f.view.filterPanel.hidden,false);button(f,'more-toggle').click();assert.equal(f.view.filterPanel.hidden,true);assert.equal(f.view.morePanel.hidden,false);button(f,'center-picker-toggle').click();assert.equal(f.view.morePanel.hidden,true);assert.equal(f.view.filterPanel.hidden,true);assert.equal(f.view.pickerHost.hidden,false);assert.equal(search.hidden,true);assert.ok(f.doc.activeElement===f.view.pickerSearch);f.view.keydown(findKey({key:'Escape',metaKey:false}));assert.equal(f.view.pickerHost.hidden,true);assert.equal(search.hidden,false);assert.equal(f.doc.activeElement?.dataset.relationFocus,'center-picker-toggle');button(f,'center-picker-toggle').click();f.view.keydown(findKey());assert.equal(f.view.pickerHost.hidden,true);assert.equal(search.hidden,false);assert.equal(f.view.filterPanel.hidden,true);assert.ok(f.doc.activeElement===search);button(f,'filter-toggle').click();assert.equal(f.view.pickerHost.hidden,true);assert.equal(f.view.filterPanel.hidden,false);});
test('the recent strip keeps independent MRU semantics and disappears entirely without valid records',async()=>{const f=await fixture();assert.equal(f.view.recentHost.hidden,false);assert.equal(f.view.recentHost.querySelector('small'),undefined);f.view.setContext('d');f.doc.tick();f.view.setContext('a');f.doc.tick();button(f,'back').click();f.doc.tick();assert.equal(f.view.history.current,'d');assert.equal(f.view.recentHost.querySelector('.ts-local-relations-recent-list').children[0].dataset.relationFocus,'recent:d');const before=f.view.history.snapshot();f.view.recent=['gone'];f.view.paintRecent(f.snapshot);assert.equal(f.view.recentHost.hidden,true);assert.equal(f.view.recentHost.children.length,0);assert.deepEqual(f.view.history.snapshot(),before);f.view.recent=['a','d'];f.view.paintRecent(f.snapshot);assert.equal(f.view.recentHost.hidden,false);assert.deepEqual(f.view.history.snapshot(),before);});
test('Escape closes focused source information without clearing inline search or opening the source',async()=>{const f=await fixture();f.view.search.value='理由';f.view.search.oninput();f.doc.tick();const info=f.view.centerHost.querySelector('.ts-local-center-info');disclose(info);button(f,'explain').focus();f.view.keydown(findKey({key:'Escape',metaKey:false}));assert.equal(info.open,false);assert.equal(f.view.query,'理由');assert.equal(f.doc.activeElement?.dataset.relationFocus,'center-info');assert.deepEqual(f.actions,[]);});
test('Escape closes a focused heading overlay and invalidates its pending navigation without clearing the inline query',async()=>{const f=await headingFixture(3);f.view.search.value='理由';f.view.search.oninput();f.doc.tick();let guard!:()=>boolean;f.host.openHeading=(_id:string,_target:unknown,current:()=>boolean)=>{guard=current;return new Promise(()=>{});};button(f,'more-toggle').click();button(f,'heading-jump').click();const target=button(f,'heading-open:'+f.tree.items[0].id);target.focus();target.click();assert.equal(guard(),true);f.view.keydown(findKey({key:'Escape',metaKey:false,isComposing:true}));assert.equal(f.view.inspectorsHost.hidden,false);assert.equal(guard(),true);f.view.keydown(findKey({key:'Escape',metaKey:false}));assert.equal(f.view.inspectorsHost.hidden,true);assert.equal(guard(),false);assert.equal(f.view.query,'理由');assert.equal(f.doc.activeElement?.dataset.relationFocus,'more-toggle');});
for(const layer of ['more','source-info','inspectors'])test(`native Escape scope closes ${layer} before application scope can switch leaves`,async()=>{const f=await headingFixture(3);f.view.search.value='理由';f.view.search.oninput();f.doc.tick();const info=f.view.centerHost.querySelector('.ts-local-center-info');if(layer==='more'){button(f,'more-toggle').click();button(f,'return-center').focus();}else if(layer==='source-info'){disclose(info);button(f,'explain').focus();}else{button(f,'more-toggle').click();button(f,'heading-jump').click();button(f,'heading-search').focus();}const handler=f.view.scope.handlers.find((handler:any)=>handler.key==='Escape');assert.deepEqual(handler.modifiers,[]);const event=findKey({key:'Escape',metaKey:false,target:f.doc.activeElement});let nativeSwitches=0;if(handler.func(event)!==false){nativeSwitches++;f.view.app.workspace.activeView=undefined;}f.view.keydown(event);assert.equal(nativeSwitches,0);assert.equal(event.defaultPrevented,true);assert.ok(f.view.app.workspace.activeView===f.view);assert.equal(f.view.query,'理由');assert.equal(layer==='more'?f.view.morePanel.hidden:layer==='source-info'?!info.open:f.view.inspectorsHost.hidden,true);assert.equal(f.doc.activeElement?.dataset.relationFocus,layer==='source-info'?'center-info':'more-toggle');assert.equal(f.view.focusVisible(f.doc.activeElement),true);});
test('native Escape scope clears a visible inline query with active-view body focus and leaves the next Escape native',async()=>{const f=await fixture();f.view.search.value='理由';f.view.search.oninput();f.doc.tick();f.doc.body!.focus();const handler=f.view.scope.handlers.find((handler:any)=>handler.key==='Escape'),event=findKey({key:'Escape',metaKey:false,target:f.doc.body});assert.equal(handler.func(event),false);f.view.keydown(event);assert.equal(f.view.query,'');assert.ok(f.doc.activeElement===f.view.search);const next=findKey({key:'Escape',metaKey:false,target:f.view.search});let nativeSwitches=0;if(handler.func(next)!==false)nativeSwitches++;assert.equal(nativeSwitches,1);assert.equal(next.defaultPrevented,false);});
for(const reason of ['hidden','other-editor','other-window','other-active-leaf','closed','composing','legacy-ime','already-prevented','modified-key'])test(`native Escape scope leaves ${reason} to its original owner`,async()=>{const f=await fixture();button(f,'more-toggle').click();button(f,'return-center').focus();const event=findKey({key:'Escape',metaKey:false,target:f.doc.activeElement});if(reason==='hidden')f.content.visible=false;if(reason==='other-editor'){const other=f.content.parentElement!.createEl('textarea');other.focus();event.target=other;}if(reason==='other-window')event.target=new El('ROOT',new Doc());if(reason==='other-active-leaf')f.view.app.workspace.activeView=undefined;if(reason==='closed')await f.view.onClose();if(reason==='composing')event.isComposing=true;if(reason==='legacy-ime')event.keyCode=229;if(reason==='already-prevented')event.defaultPrevented=true;if(reason==='modified-key')event.metaKey=true;const before=f.doc.activeElement,handler=f.view.scope.handlers.find((handler:any)=>handler.key==='Escape');assert.equal(handler.func(event),undefined);assert.ok(f.doc.activeElement===before);assert.equal(event.defaultPrevented,reason==='already-prevented');if(reason!=='closed')assert.equal(f.view.moreOpen,true);});
